PREFIX brick: <http://brickschema.org/schema/1.2/brick#>
SELECT ?zone ?sp ?sp_class WHERE {
  ?zone brick:hasSubpropertyOf* brick:Zone .
  ?zone rdfs:label ?label .
  FILTER(?label="Perimeter_mid_ZN_4")
}

