import csv
ids = {
 'cool':'c9fc3c98-8ad8-5bba-a072-0a5c02357f48',
 'heat':'dcb57f97-6711-5249-9f6f-3a81a69fc8d6',
 'temp':'c49bbc2f-096e-5e16-bead-066250790308',
}
data = {k:{} for k in ids}
with open(VALUES_CSV) as f:
    for row in csv.DictReader(f):
        ts=row['timeseries_id']
        if ts in ids.values():
            key=list(ids)[list(ids.values()).index(ts)]
            if row['timestamp'].startswith('2018-07-04'):
                data[key][row['timestamp']]=float(row['value'])

for k in data:
    print(k, len(data[k]), min(data[k].values()) if data[k] else None, max(data[k].values()) if data[k] else None)

all_ts = sorted(set(data['temp'])&set(data['cool'])&set(data['heat']))
print('common hours:', len(all_ts))
violate=[]
for ts in all_ts:
    t=data['temp'][ts]; c=data['cool'][ts]; h=data['heat'][ts]
    if not (h <= t <= c):
        violate.append((ts,t,h,c))
print('violations:', len(violate))
for v in violate[:10]: print(v)
print('within setpoints all hours:', len(violate)==0 and len(all_ts)>0)
